appendRecurrenceItem(aItem) {
  this.ensureBaseItem();
  this.ensureMutable();
  this.ensureSortedRecurrenceRules();

  aItem = aItem?.wrappedJSObject || aItem;
  this.mRecurrenceItems.push(aItem);
  if (aItem.isNegative) {
    this.mNegativeRules.push(aItem);
  } else {
    this.mPositiveRules.push(aItem);
  }
},
